from scipy.spatial import Voronoi
from shapely.geometry import Polygon, Point, box, LineString, MultiLineString
from shapely.ops import polygonize, unary_union
import numpy as np

# Recompute Voronoi
vor = Voronoi(points)

# Use a much larger bounding box for clipping unbounded rays
margin = 5.0
large_bbox = box(min_lon - margin, min_lat - margin, max_lon + margin, max_lat + margin)
original_bbox = box(min_lon, min_lat, max_lon, max_lat)

all_polygons = {}

for point_idx in range(len(points)):
    # Find all ridge indices that involve this point
    region_ridge_indices = []
    for ridge_idx, (p1, p2) in enumerate(vor.ridge_points):
        if p1 == point_idx or p2 == point_idx:
            region_ridge_indices.append(ridge_idx)

    if not region_ridge_indices:
        continue

    # Build the region polygon by ordering vertices around the point
    # For each ridge, determine the correct ordering of vertices
    # We need to collect all vertices (finite and infinite) in order

    # First, collect all finite vertices for this region
    region_vertices = set()
    for ridge_idx in region_ridge_indices:
        v1, v2 = vor.ridge_vertices[ridge_idx]
        if v1 != -1:
            region_vertices.add(v1)
        if v2 != -1:
            region_vertices.add(v2)

    # Get the region index from vor.point_region
    region_idx = vor.point_region[point_idx]
    region_vertex_indices = vor.regions[region_idx]

    if -1 in region_vertex_indices:
        # Unbounded region: need to construct rays for infinite vertices
        # Sort vertices in order around the point
        # The region vertices are already in order, with -1 indicating infinite

        # Build ordered list of finite vertices and infinite placeholders
        ordered_vertices = []
        for vi in region_vertex_indices:
            if vi != -1:
                ordered_vertices.append(('finite', vor.vertices[vi]))
            else:
                ordered_vertices.append(('infinite', None))

        # Now fill in the infinite vertices by computing ray intersections with large bbox
        # Find which ridges correspond to the infinite vertices
        # An infinite vertex appears between two finite vertices in the region

        filled_vertices = []
        n = len(ordered_vertices)
        for j in range(n):
            curr = ordered_vertices[j]
            if curr[0] == 'finite':
                filled_vertices.append(curr[1])
            else:
                # Infinite vertex: find the two adjacent finite vertices
                # Search for the finite vertices before and after
                prev_finite = None
                next_finite = None

                # Look backward
                for k in range(j-1, -1, -1):
                    if ordered_vertices[k][0] == 'finite':
                        prev_finite = ordered_vertices[k][1]
                        break
                if prev_finite is None:
                    for k in range(n-1, -1, -1):
                        if ordered_vertices[k][0] == 'finite':
                            prev_finite = ordered_vertices[k][1]
                            break

                # Look forward
                for k in range(j+1, n):
                    if ordered_vertices[k][0] == 'finite':
                        next_finite = ordered_vertices[k][1]
                        break
                if next_finite is None:
                    for k in range(0, n):
                        if ordered_vertices[k][0] == 'finite':
                            next_finite = ordered_vertices[k][1]
                            break

                if prev_finite is not None and next_finite is not None:
                    # The infinite ray direction is perpendicular to the line between
                    # the two finite vertices, pointing outward
                    mid = (prev_finite + next_finite) / 2.0
                    # Direction from prev to next
                    edge_vec = next_finite - prev_finite
                    # Perpendicular (rotate 90 degrees)
                    perp = np.array([-edge_vec[1], edge_vec[0]])
                    # Normalize
                    norm = np.linalg.norm(perp)
                    if norm > 0:
                        perp = perp / norm

                    # Determine which direction is outward (away from the point)
                    pt = points[point_idx]
                    vec_to_pt = pt - mid
                    if np.dot(perp, vec_to_pt) > 0:
                        perp = -perp

                    # Extend ray to intersect large bbox
                    # Find intersection of ray from mid with large bbox
                    ray_start = mid
                    ray_end = mid + perp * 20.0  # 20 degrees
                    ray_line = LineString([tuple(ray_start), tuple(ray_end)])

                    # Intersect with large bbox boundary
                    bbox_boundary = large_bbox.boundary
                    intersection = ray_line.intersection(bbox_boundary)

                    if not intersection.is_empty:
                        if intersection.geom_type == 'Point':
                            filled_vertices.append((intersection.x, intersection.y))
                        elif intersection.geom_type == 'MultiPoint':
                            # Take the farthest point from ray_start
                            pts_list = list(intersection.geoms)
                            farthest = max(pts_list, key=lambda p: Point(ray_start).distance(p))
                            filled_vertices.append((farthest.x, farthest.y))
                        else:
                            filled_vertices.append(tuple(ray_end))
                    else:
                        filled_vertices.append(tuple(ray_end))
                else:
                    # Fallback: use the point itself
                    filled_vertices.append(tuple(points[point_idx]))

        # Build polygon from filled vertices
        if len(filled_vertices) >= 3:
            poly = Polygon(filled_vertices)
            if not poly.is_valid:
                poly = poly.buffer(0)
            # Clip to original bounding box
            clipped = poly.intersection(original_bbox)
            if not clipped.is_empty:
                all_polygons[point_idx] = clipped
    else:
        # Bounded region: all vertices are finite
        verts = [vor.vertices[vi] for vi in region_vertex_indices]
        if len(verts) >= 3:
            poly = Polygon(verts)
            if not poly.is_valid:
                poly = poly.buffer(0)
            clipped = poly.intersection(original_bbox)
            if not clipped.is_empty:
                all_polygons[point_idx] = clipped

print(f"Number of Voronoi cells reconstructed: {len(all_polygons)}")

# Convert to projected CRS and compute areas
station_polygons_m_final = {}
for i, poly_ll in all_polygons.items():
    def to_projected(geom):
        if geom.is_empty:
            return None
        if geom.geom_type == 'Polygon':
            coords = [transformer_to_m.transform(x, y) for x, y in geom.exterior.coords]
            return Polygon(coords)
        elif geom.geom_type == 'MultiPolygon':
            parts = []
            for part in geom.geoms:
                coords = [transformer_to_m.transform(x, y) for x, y in part.exterior.coords]
                parts.append(Polygon(coords))
            return unary_union(parts)
        elif geom.geom_type == 'GeometryCollection':
            polys = [g for g in geom.geoms if g.geom_type == 'Polygon']
            if polys:
                parts = []
                for part in polys:
                    coords = [transformer_to_m.transform(x, y) for x, y in part.exterior.coords]
                    parts.append(Polygon(coords))
                return unary_union(parts)
        return None

    poly_m = to_projected(poly_ll)
    if poly_m is not None and not poly_m.is_empty:
        station_polygons_m_final[i] = poly_m

print(f"Number of valid projected cells: {len(station_polygons_m_final)}")

# Calculate areas
areas_final = {}
for i, poly_m in station_polygons_m_final.items():
    area_m2 = poly_m.area
    area_km2 = area_m2 / 1_000_000
    areas_final[i] = area_km2

